function rig(t){const root=fs.mkdtempSync(path.join(os.tmpdir(),'orbit-broker-')),key=crypto.randomBytes(32),storage={available:()=>true,seal(v){const iv=crypto.randomBytes(12),c=crypto.createCipheriv('aes-256-gcm',key,iv);return {iv:iv.toString('hex'),tag:(()=>{const data=Buffer.concat([c.update(JSON.stringify(v)),c.final()]);this.data=data.toString('hex');return c.getAuthTag().toString('hex');})(),data:this.data};},open(v){const d=crypto.createDecipheriv('aes-256-gcm',key,Buffer.from(v.iv,'hex'));d.setAuthTag(Buffer.from(v.tag,'hex'));return JSON.parse(Buffer.concat([d.update(Buffer.from(v.data,'hex')),d.final()]).toString());}};const home=new Home(root,{secretStorage:storage}).ensure();home.createAgent({name:'Alex'});t.after(()=>fs.rmSync(root,{recursive:true,force:true}));return {root,home,storage};}
