async function start(t,r,c=config(),f=async url=>response(url.endsWith('countTokens')?{totalTokens:5}:reply()),prior){const job=prior||r.home.createJob('alex','Goal'),runs=createJobRuns(),ctl=new AbortController(),run=runs.begin('alex',job.id,ctl.signal);r.home.updateJob('alex',job.id,{status:'running',runId:run.runId});const b=await broker.start({home:r.home,job:r.home.findJob(job.id),run,runs,cfg:c,signal:ctl.signal,fetchImpl:f,askNative:async req=>{req.onDecision?.({id:'trusted-fixture',origin:'human_main_window'});return 'once';},decide:()=>({level:'ask'})});t.after(()=>{b.close();runs.end(run);});const call=(messages=[{role:'user',content:'Goal'}],extra={})=>fetch(b.override.workerBaseUrl+'/chat/completions',{method:'POST',headers:{Authorization:'Bearer '+b.override.workerApiKey,'Content-Type':'application/json'},body:JSON.stringify({model:'fixture',messages,...extra})});return {b,call,job,ctl,runs,run};}
test('native Gemini reserves before upstream generation and exposes only local credentials',async t=>{const r=rig(t),requests=[];const x=await start(t,r,config(),async(url,o)=>{requests.push({url,body:JSON.parse(o.body)});if(url.endsWith('generateContent'))assert.equal(r.home.findJob(x.job.id).tokenBudget.reservedTokens,15);return response(url.endsWith('countTokens')?{totalTokens:5}:reply());});const res=await x.call();assert.equal(res.status,200);const job=r.home.findJob(x.job.id);assert.equal(job.tokenBudget.measuredInput,5);assert.equal(job.tokenBudget.measuredOutput,2);assert.equal(requests[1].body.generationConfig.maxOutputTokens,10);assert.deepEqual(requests[0].body.generateContentRequest.contents,requests[1].body.contents);assert.equal(x.b.override.workerProvider,'custom');assert.notEqual(x.b.override.workerApiKey,config().apiKey);assert.doesNotMatch(fs.readFileSync(require('../lib/job-storage').jobFile(r.home,'alex',job.id),'utf8'),/CANARY_UPSTREAM_KEY|Fixture answer/);});
